function persist({index=true}={}){if(storageTransition)return Promise.resolve(false);if(!dirty&&p?.storage_token)return Promise.resolve(true);const source=p,snapshot=clone(p);saving=saving.catch(()=>{}).then(async()=>{snapshot.storage_token=source.storage_token;await projectStore.save(snapshot);source.storage_token=snapshot.storage_token;if(p===source&&p.revision===snapshot.revision)dirty=false;let indexError=null;if(index&&directoryProject(snapshot)&&!projectVersions(snapshot).some(v=>v.fs_ref||v.returned_ref))try{await originals.saveIndex(snapshot)}catch(e){indexError=e}if(p.id===snapshot.id)$('#saveStatus').textContent=indexError?'本機索引已保存；資料夾索引待更新':directoryProject(snapshot)?'分類與縮圖已儲存':'本機已儲存';return true}).catch(e=>{$('#saveStatus').textContent='儲存失敗，請立即備份';if(e.code==='project_conflict'){clearTimeout(saveTimer);modal('其他分頁已更新此專案',`<p>最新資料已保留。此分頁尚未保存的內容也仍在畫面上。</p><button id="keepConflictCopy" class="primary">另存目前內容為新專案</button> <button id="loadLatestProject">重新開啟最新版本</button>`);$('#keepConflictCopy').onclick=async()=>{try{const copy=importedProject(p,uid());copy.name=p.name+'（衝突副本）';await projectStore.save(copy);p=copy;resetProjectWorkspace();renderAll();$('#modal').close();toast('此分頁內容已另存，原專案保留最新版本')}catch(error){toast(error.message,true)}};$('#loadLatestProject').onclick=async()=>{p=await projectStore.get(p.id);resetProjectWorkspace();renderAll();$('#modal').close();toast('已開啟最新版本')}}else toast('無法儲存，請匯出備份：'+e.message,true);return false});return saving}

async function prepareAccountNavigation(){
 if(busy||storageTransition)throw Error('請等待目前的上傳、搬移或保存操作完成，再登入或登出');
 if(!p||!projectStore)return {saved:false};
 workspaceUI.closePanels({restoreFocus:false});busy=true;blockProjectTransition(true);$('#runsView').inert=true;
 try{clearTimeout(saveTimer);if(!await persist({index:false}))throw Error('目前專案尚未保存，已停止登入／登出；請先處理保存問題');return {saved:true}}
 finally{busy=false;blockProjectTransition(false);$('#runsView').inert=false;syncAssetToolbar()}
}
function releasePreviewURLs(){for(const url of previewURLs)URL.revokeObjectURL(url);previewURLs.length=0}
async function makeThumbnail(blob){
 const url=URL.createObjectURL(blob);
 try{const image=new Image();image.src=url;await image.decode();const ratio=Math.min(1,160/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png')}finally{URL.revokeObjectURL(url)}
}
async function runStorageOperation(action){
 if(busy)throw Error('請等待目前操作完成');workspaceUI.closePanels({restoreFocus:false});busy=true;blockProjectTransition(true);$('#runsView').inert=true;
 try{clearTimeout(saveTimer);if(!await persist({index:false}))throw Error('目前專案保存失敗，已停止搬移');storageTransition=true;await action()}
 finally{storageTransition=false;busy=false;blockProjectTransition(false);$('#runsView').inert=false;syncAssetToolbar()}
}
