function confirmTaskAction(action,runId){
 if(busy){toast('請等待目前操作完成');return}
 const run=p.runs.find(run=>run.id===runId);if(!run)return;
 const projectId=p.id,title={cancel:'取消任務',resume:'恢復任務',delete:'刪除任務'}[action];
 const description=action==='cancel'?'取消後停止本機匯入與驗收，保留固定規格與候選圖，可隨時恢復。助手交接區將同步停用此任務；助手已讀取並開始的工作仍需在對話中停止。':action==='delete'?'任務將移入「已刪除任務」，可隨時復原。已加入素材庫或已保存到裝置的圖片會保留。':'恢復後可繼續匯入候選圖與驗收，使用原本的固定規格。';
 modal(title,`<p><strong>${esc(run.spec.shot_id||run.spec.shot)}</strong></p><p>${description}</p><button id="confirmTaskAction" class="${action==='delete'?'danger':'primary'}">確認${title}</button> <button id="dismissTaskAction">返回</button>`);
 $('#dismissTaskAction').onclick=()=>$('#modal').close();$('#confirmTaskAction').onclick=()=>{if(projectId===p.id)applyTaskAction(action,runId)};
}
async function applyTaskAction(action,runId){
 if(busy)return;workspaceUI.closePanels({restoreFocus:false});busy=true;blockProjectTransition(true);$('#runsView').inert=true;
 try{
  if(['cancel','delete'].includes(action)){const source=p.runs.find(r=>r.id===runId);if(source?.handoff){for(const v of p.versions.filter(v=>v.returned_ref?.task_id===source.handoff.task_id&&!v.retained_ref)){Object.assign(v,await retainReturnedImage(v));changed();if(!await persist())throw Error('正式素材尚未保存，已停止任務操作')}}}
  ({cancel:cancelTask,resume:resumeTask,delete:deleteTask,restore:restoreTask}[action])(p,runId);
  if(outputRun===runId)outputRun=null;
  const run=allProjectRuns(p).find(r=>r.id===runId),state=deletedTasks(p).some(e=>e.run.id===runId)?'deleted':run.status==='cancelled'?'cancelled':'active';
  queueHandoffControl(p,run,state);
  changed();if(!await persist())throw Error('任務操作尚未保存，請立即備份此專案');
  $('#modal').close();renderAll();renderRuns();
  if(ownsHandoff(p,run))try{await syncHandoffControl({project:p,run,save:saveHandoff})}catch(e){throw Error('本機任務已更新；助手交接狀態尚未同步，請按「接收回傳」重試：'+e.message)}
  toast({cancel:'任務已取消，可恢復',resume:'任務已恢復',delete:'任務已刪除，可從已刪除任務復原',restore:'已復原任務與候選圖'}[action]);
 }catch(e){renderRuns();toast(e.message,true)}finally{busy=false;blockProjectTransition(false);$('#runsView').inert=false;renderRuns();syncAssetToolbar()}
}
function review(r,o,decision){try{assertTaskActive(p,r.id)}catch(e){toast(e.message,true);return}if(decision==='accepted'&&!confirm('確認已檢查角色外觀、動作與場景，並核定這張候選圖？'))return;if(decision==='rejected'&&!o.issues.trim()){toast('退回前請先填寫需要修改的問題',true);return}o.decision=decision;o.reviews.push({decision,issues:o.issues,reviewer:'使用者',created_at:new Date().toISOString()});r.status=r.outputs.every(o=>o.decision!=='pending')?'reviewed':'needs_review';changed();renderRuns();toast(decision==='accepted'?'已記錄人工核定':'已記錄退回與修改問題')}
async function backup({complete=false}={}){if(busy)return;busy=true;try{const files=await projectBackupFiles(p,{includeOriginals:complete,readOriginal:(project,v)=>originals.read(project,v)}),archive=zip(files);if(archive.size>BACKUP_BYTES)throw Error('備份檔超過可還原大小 '+formatMiB(BACKUP_BYTES));download(archive,p.name.replace(/[^\p{L}\p{N}_-]/gu,'_')+'_專案備份.zip');toast('已備份專案、縮圖與原圖來源；裝置圖片請連同資料夾保留')}catch(e){toast(e.message,true)}finally{busy=false;syncAssetToolbar()}}
async function restore(file){if(busy)return;if(/\.json$/i.test(file.name)){try{if(file.size>64*1024*1024)throw Error('專案索引過大');const input=JSON.parse(await file.text());await validateDirectoryIndex(input);await originalStorageUI.importManifest(input)}catch(e){toast('匯入失敗：'+e.message,true)}return}busy=true;try{if(file.size>BACKUP_BYTES)throw Error('備份檔超過 '+formatMiB(BACKUP_BYTES));const files=await unzip(await file.arrayBuffer());if(!files['project.json']||!files['backup-manifest.json'])throw Error('請匯入「備份專案」產生的 ZIP，生成包不能用來恢復專案');const q=JSON.parse(new TextDecoder().decode(files['project.json']));if(q.schema_version!=='0.1'||!Array.isArray(q.assets)||!Array.isArray(q.versions)||!Array.isArray(q.nodes)||!Array.isArray(q.edges)||!Array.isArray(q.runs)||!q.nodes.some(n=>n.id==='generation')||q.nodes.length>500||q.runs.length>500)throw Error('備份結構或版本不支援');validateAssetFolders(q);validateTaskCollections(q);const m=JSON.parse(new TextDecoder().decode(files['backup-manifest.json']));if(!Array.isArray(m.files))throw Error('備份索引損壞');for(const entry of m.files)if(!files[entry.path]||files[entry.path].length!==entry.byte_size||await hash(files[entry.path])!==entry.sha256)throw Error('備份檔案遺失或雜湊不符');const all=projectVersions(q);const validId=id=>typeof id==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(id);for(const list of [q.versions,q.assets,q.edges,allProjectRuns(q),allProjectRuns(q).flatMap(r=>r.outputs)]){if(list.some(x=>!validId(x.id))||new Set(list.map(x=>x.id)).size!==list.length)throw Error('備份識別碼無效或重複')}if(q.nodes.some(n=>n.id!=='generation'&&!validId(n.id)))throw Error('節點識別碼無效');let total=0;for(const v of all){if(m.mode==='references-v1'&&!v.path){if(v.data)throw Error('來源備份不可夾帶未驗證原圖');validateExternalVersion(v);continue}const data=files[v.path];if(!data||!['image/png','image/jpeg','image/webp'].includes(v.mime)||data.length>MAX_FILE||await hash(data)!==v.sha256)throw Error('素材版本或雜湊不符');total+=data.length;if(total>MAX_TOTAL)throw Error(capacityError(total));const blob=new Blob([data],{type:v.mime});const checked=await readImage(new File([blob],v.name,{type:v.mime}),v.source,false);v.data=checked.data;delete v.disk_ref;delete v.fs_ref;delete v.returned_ref;delete v.retained_ref;delete v.thumbnail;delete v.path}for(const n of q.nodes){if(typeof n.id!=='string'||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.y<0||n.x>1400||n.y>1300||n.id!=='generation'&&!q.versions.some(v=>v.id===n.versionId))throw Error('畫布節點資料損壞')}if(new Set(q.nodes.map(n=>n.id)).size!==q.nodes.length)throw Error('節點識別碼重複');for(const key of ['name','shot','instruction','preserve','changes','ratio'])if(typeof q[key]!=='string')throw Error('專案欄位損壞');for(const e of q.edges){if(!q.nodes.some(n=>n.id===e.from)||e.to!=='generation'||e.from==='generation'||!ROLES[e.role]||!['subject','include','exclude','priority'].every(k=>typeof e[k]==='string'))throw Error('連線資料損壞')}for(const a of q.assets)if(!q.versions.some(v=>v.id===a.currentVersionId)||typeof a.name!=='string')throw Error('素材資料損壞');for(const r of allProjectRuns(q)){if(await hash(stable(r.spec))!==r.spec_hash||!Array.isArray(r.spec.references))throw Error('歷史快照雜湊不符');for(const ref of r.spec.references){const v=q.versions.find(v=>v.id===ref.asset_version_id);if(!v||v.sha256!==ref.sha256)throw Error('歷史參考版本遺失')}}if(!confirm('備份驗證通過。將「'+q.name+'」新增為另一個專案，現有專案會保留。要匯入嗎？'))return;clearTimeout(saveTimer);if(!await persist())throw Error('目前專案尚未儲存，已停止匯入');const imported=importedProject(q,uid());if(m.mode!=='references-v1')delete imported.image_storage;await projectStore.save(imported);p=imported;resetProjectWorkspace();renderAll();fit();toast('已新增匯入專案，原有專案仍保留')}catch(e){toast('匯入失敗：'+e.message,true)}finally{busy=false;syncAssetToolbar()}}
async function makeDemo(){p=fresh();p.name='我的第一個畫面';p.shot='DEMO-001';p.instruction='依場景參考，呈現主角坐在窗邊，抬頭看向窗外。保留角色外觀與服裝，採用動作圖的姿勢。';p.preserve='角色外觀、服裝；場景的窗戶、桌椅與空間配置。';p.changes='表情、視線與鏡頭構圖。';const demos=[['角色 A · 外觀示意','identity','主角 A'],['窗邊空間 · 場景示意','scene','場景 A'],['坐姿 · 動作示意','pose','主角 A']];for(let i=0;i<demos.length;i++){const [name,kind,subject]=demos[i],canvas=document.createElement('canvas');canvas.width=640;canvas.height=360;const c=canvas.getContext('2d');c.fillStyle=['#41616a','#8b8772','#726c87'][i];c.fillRect(0,0,640,360);if(i===1){c.fillStyle='#b4bca2';c.fillRect(340,30,215,210);c.fillStyle='#e8ddbc';c.fillRect(352,42,90,185);c.fillRect(453,42,90,185);c.fillStyle='#b2a08a';c.beginPath();c.moveTo(0,275);c.lineTo(640,235);c.lineTo(640,360);c.lineTo(0,360);c.fill();c.fillStyle='#4d534b';c.fillRect(150,210,240,18);c.fillRect(170,228,12,110);c.fillRect(365,228,12,85);c.fillStyle='#d1c5a5';c.fillRect(87,194,45,105);c.fillStyle='#6b7760';c.fillRect(98,70,30,120);c.beginPath();c.ellipse(75,85,38,20,-.6,0,7);c.ellipse(143,125,42,20,.5,0,7);c.fill()}else{c.fillStyle=i===0?'#51757b':'#827c94';c.beginPath();c.arc(320,200,180,0,7);c.fill();c.fillStyle='#d8bc9d';c.beginPath();c.ellipse(320,117,47,58,0,0,7);c.fill();c.fillStyle='#263b41';c.beginPath();c.ellipse(319,82,52,34,-.15,0,7);c.fill();c.beginPath();c.moveTo(270,180);c.quadraticCurveTo(315,153,365,185);c.lineTo(i===0?402:385,360);c.lineTo(235,360);c.closePath();c.fillStyle=i===0?'#cad6c7':'#ded5bd';c.fill();if(i===2){c.strokeStyle='#d8bc9d';c.lineWidth=25;c.lineCap='round';c.beginPath();c.moveTo(361,205);c.lineTo(410,263);c.lineTo(488,255);c.stroke();c.fillStyle='#434b5a';c.fillRect(380,275,180,12);c.fillRect(510,285,10,75)}else{c.strokeStyle='#97b6ac';c.lineWidth=3;c.beginPath();c.moveTo(320,193);c.lineTo(320,357);c.stroke()}}c.fillStyle='#12252d88';c.fillRect(14,14,110,25);c.font='13px sans-serif';c.fillStyle='#edf3e2';c.fillText('DEMO / 示意',24,32);const data=canvas.toDataURL('image/png'),v={id:uid(),name,mime:'image/png',byte_size:dataBytes(data).length,width:640,height:360,data,sha256:await hash(dataBytes(data)),source:'demo',created_at:new Date().toISOString()};p.versions.push(v);const a={id:uid(),name,kind,currentVersionId:v.id,version:1};p.assets.push(a);const n={id:uid(),versionId:v.id,x:45,y:45+i*245};p.nodes.push(n);const e=makeEdge(n.id,kind);e.subject=subject;p.edges.push(e)}p.nodes[0].x=415;p.nodes[0].y=220}
function help(){modal('使用映構',`<ol><li>開啟「素材庫 → 裝置資料夾」，按「連接資料夾」選擇今天使用的位置。</li><li>網站照實列出資料夾與 PNG、JPG、WebP 圖片。圖片在下一層時可勾「包含子資料夾圖片」，每張會顯示實際所在路徑。可建立資料夾，進入後可繼續建立子資料夾。</li><li>按圖片的「加入畫布」或將圖片拖到畫布，再設定角色、場景與採用條件。原圖保持在裝置原位置。</li><li>「更換位置」只切換瀏覽來源；「重新整理」重新讀取裝置內容。</li><li>按「傳送任務」直接交接規格與必要原圖。送出後回到對話請助手讀取，不需下載 ZIP。</li><li>按「更新狀態／接收回傳」核對交接狀態並顯示候選圖；未連接裝置時也能預覽及驗收，按候選圖的「存入裝置資料夾」再選擇位置保存原圖。</li></ol><p>專案引用保留原始圖片位置與雜湊。原檔被改動、移動、刪除或權限失效時，需要重新連接或選回相同原圖，縮圖不會代替原圖。來源未授權時可繼續查看已保存的縮圖。</p><p>舊專案的素材及任務仍保留在「專案引用」。舊版原圖修復與分類副本工具可至右上角設定；來源資料夾的變更與備份由你管理。</p><button id="helpRestore">匯入專案備份</button>`);$('#helpRestore').onclick=()=>{$('#modal').close();$('#restoreInput').click()}}

$('#closeModal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close()}};$('#fileInput').accept=IMAGE_ACCEPT;$('#outputInput').accept=IMAGE_ACCEPT;$('#uploadBtn').onclick=()=>{if(busy){toast('請等待目前操作完成');return}$('#fileInput').click()};$('#fileInput').onchange=async e=>{await handleUploads([...e.target.files]);e.target.value=''};$('#outputInput').onchange=async e=>{await handleUploads([...e.target.files],true);e.target.value=''};$('#projectName').oninput=e=>{p.name=e.target.value;changed()};$('#search').oninput=renderAssets;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderAssets()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#backCanvas').onclick=()=>{showView('canvas');fit()};$('#fitBtn').onclick=fit;$('#zoomIn').onclick=()=>zoom(1.15);$('#zoomOut').onclick=()=>zoom(1/1.15);$('#undoBtn').onclick=undoLastEdit;$('#selectAssetsBtn').onclick=()=>{assetSelectionMode=!assetSelectionMode;if(!assetSelectionMode)assetSelection.clear();renderAssets()};$('#selectVisibleAssets').onclick=()=>{const shown=visibleAssets(),all=shown.every(a=>assetSelection.has(a.id));for(const a of shown){if(all)assetSelection.delete(a.id);else assetSelection.add(a.id)}renderAssets()};$('#clearAssetSelection').onclick=()=>{assetSelection.clear();renderAssets()};$('#deleteAssetsBtn').onclick=()=>confirmAssetDeletion();$('#moveAssetsBtn').onclick=()=>showMoveAssets([...assetSelection]);$('#newFolderBtn').onclick=()=>showFolderEditor();$('#renameFolderBtn').onclick=()=>showFolderEditor(currentFolder);$('#deleteFolderBtn').onclick=confirmFolderRemoval;$('#undoAssetDelete').onclick=undoLastEdit;$('#checkBtn').onclick=checkSpec;$('#exportBtn').onclick=previewExport;$('#mobileSendTaskBtn').onclick=previewExport;$('#refreshHandoffBtn').onclick=refreshHandoff;$('#backupBtn').onclick=backup;$('#fullBackupBtn').onclick=()=>backup({complete:true});$('#restoreBtn').onclick=()=>$('#restoreInput').click();$('#restoreInput').onchange=async e=>{if(e.target.files[0])await restore(e.target.files[0]);e.target.value=''};$('#helpBtn').onclick=help;$('#projectsBtn').onclick=showProjectManager;window.addEventListener('beforeunload',()=>{if(p&&db&&!storageTransition){clearTimeout(saveTimer);persist()}});window.addEventListener('resize',()=>{if(view==='canvas')fit()});
async function init(){try{projectStore=await openProjectStore();db=projectStore.db;p=await projectStore.active();if(!p){const projects=await projectStore.list();if(projects.length){p=await projectStore.get(projects[0].id);await projectStore.activate(p.id)}else {p=fresh();if(!await persist())throw Error('無法儲存第一個專案')}}busy=false;blockProjectTransition(false);renderAll();requestAnimationFrame(fit);$('#saveStatus').textContent='本機已儲存';deviceFolderUI.restore();originalStorageUI.restore();await sourceFolderUI.restore()}catch(e){busy=true;sourceFolderUI.update();$('#saveStatus').textContent='專案尚未開啟';modal('無法開啟專案清單',`<p>${esc(e.message)}</p><p>請允許網站使用瀏覽器儲存空間。若另一個分頁正在開啟舊版，請先關閉舊分頁，再重新整理；原有資料會保留。</p>`)}}

$('#canvas').ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy'};$('#canvas').ondrop=e=>{e.preventDefault();const source=e.dataTransfer.getData('application/x-yinggou-source');if(source){try{sourceFolderUI.addDragged(JSON.parse(source))}catch{toast('圖片來源無效，請重新從資料夾選取',true)}}else toast('請從已連接的資料夾拖曳圖片，或按圖片上的「加入畫布」')};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&p&&db&&!storageTransition){clearTimeout(saveTimer);persist()}});
blockProjectTransition(true);
queueMicrotask(init);

let projectManagerGeneration=0;
function renderProjectStatus(){if(p)renderCapacity()}
function resetProjectWorkspace(){clearTimeout(saveTimer);undo=[];assetSelection.clear();assetSelectionMode=false;currentFolder='all';selected='generation';filter='all';outputRun=null;$('#search').value='';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));$('.library').classList.remove('open');$('#inspector').classList.remove('open');showView('canvas');deviceFolderUI.restore();originalStorageUI.restore()}
function blockProjectTransition(value){$('#canvasView').inert=value;$('#projectName').disabled=value}
async function switchProject(id){if(busy){toast('請等待目前的素材或保存操作完成');return}if(id===p.id){$('#modal').close();return}busy=true;blockProjectTransition(true);try{clearTimeout(saveTimer);if(!await persist())throw Error('目前專案尚未保存，已停止切換');const next=await projectStore.get(id);if(!next)throw Error('找不到此專案');await projectStore.activate(id);p=next;resetProjectWorkspace();renderAll();fit();$('#modal').close();toast('已開啟「'+p.name+'」')}catch(e){toast(e.message,true)}finally{busy=false;blockProjectTransition(false);syncAssetToolbar()}}
function showNewProjectDialog(){if(busy){toast('請等待目前操作完成');return}modal('新增專案',`<label>專案名稱<input id="newProjectName" maxlength="200" placeholder="例如：現實遊戲 EP01" value="新專案"></label>${directoryProject(p)?'<label class="toggle-label"><input id="inheritOriginalStorage" type="checkbox" checked>沿用目前的原圖資料夾（不設專案原圖總量上限）</label>':''}<p>現有專案的素材、畫布與任務會保留。</p><button id="createProjectConfirm" class="primary">建立專案</button>`);$('#newProjectName').focus();$('#newProjectName').select();$('#createProjectConfirm').onclick=async()=>{if(busy)return;const name=$('#newProjectName').value.trim(),inheritStorage=$('#inheritOriginalStorage')?.checked?clone(p.image_storage):null;if(!name){toast('請填寫專案名稱',true);return}busy=true;blockProjectTransition(true);try{clearTimeout(saveTimer);if(!await persist())throw Error('目前專案尚未保存，已停止建立');const next=fresh();next.name=name;if(inheritStorage)next.image_storage=inheritStorage;await projectStore.save(next);p=next;resetProjectWorkspace();renderAll();fit();$('#modal').close();toast('已新增專案')}catch(e){toast(e.message,true)}finally{busy=false;blockProjectTransition(false);syncAssetToolbar()}}}
async function showProjectManager(){
 if(busy){toast('請等待目前操作完成');return}
 const generation=++projectManagerGeneration;if(!await persist())return;const local=await projectStore.list();if(generation!==projectManagerGeneration)return;
 const card=x=>`<article class="project-card"><div><strong>${esc(x.name||'未命名專案')}</strong>${x.id===p.id?'<span class="chip">目前開啟</span>':''}<p>${x.assets} 張素材 · ${x.runs} 個任務<br>${esc(new Date(x.updated_at).toLocaleString('zh-TW'))}</p></div><div class="project-card-actions"><button data-open-project="${x.id}">${x.id===p.id?'返回工作台':'開啟'}</button><button data-copy-project="${x.id}">另存副本</button>${x.id===p.id?'':`<button data-archive-project="${x.id}">${x.archived_at?'恢復到專案列表':'封存'}</button>`}</div></article>`;
 modal('我的專案',`<div class="project-manager-actions"><button id="managerNewProject" class="primary">＋ 新增專案</button><button id="managerBackupProject">備份目前專案</button><button id="managerImportProject">匯入備份</button></div><p class="project-manager-note">切換前自動保存；封存可復原，不會刪除照片或任務。正在開啟的專案請先切換後再封存。</p>${p.entry_copy?'<p class="project-manager-note">目前專案從原入口複製而來；兩個入口不會自動同步，請以此處繼續編輯。</p>':''}<div id="localProjectList">${local.filter(x=>!x.archived_at).map(card).join('')}</div><details class="form-details"><summary>已封存專案（${local.filter(x=>x.archived_at).length}）</summary>${local.filter(x=>x.archived_at).map(card).join('')||'<p>沒有已封存專案</p>'}</details>`);
 $('#managerNewProject').onclick=showNewProjectDialog;$('#managerBackupProject').onclick=()=>{$('#modal').close();backup()};$('#managerImportProject').onclick=()=>{$('#modal').close();$('#restoreInput').click()};document.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>switchProject(b.dataset.openProject));document.querySelectorAll('[data-copy-project]').forEach(b=>b.onclick=()=>copyLocalProject(b.dataset.copyProject));document.querySelectorAll('[data-archive-project]').forEach(b=>b.onclick=()=>archiveLocalProject(b.dataset.archiveProject));
}
async function archiveLocalProject(id){
 if(busy||id===p.id)return;busy=true;
 try{const target=await projectStore.get(id);if(!target)throw Error('找不到專案');if(target.archived_at)delete target.archived_at;else target.archived_at=new Date().toISOString();target.revision++;target.updated_at=new Date().toISOString();await projectStore.save(target,false)}catch(e){toast(e.message,true)}finally{busy=false}await showProjectManager();
}
async function copyLocalProject(id){if(busy)return;busy=true;blockProjectTransition(true);try{clearTimeout(saveTimer);if(!await persist())throw Error('目前專案尚未保存');const source=await projectStore.get(id);if(!source)throw Error('專案遺失');const copy=importedProject(source,uid());copy.name=source.name+'（副本）';await projectStore.save(copy);p=copy;resetProjectWorkspace();renderAll();fit();$('#modal').close();toast('已建立獨立副本')}catch(e){toast(e.message,true)}finally{busy=false;blockProjectTransition(false);syncAssetToolbar()}}
document.addEventListener('project-storage-blocked',()=>toast('請先關閉此網站的其他舊分頁，再重新整理，以升級原圖資料夾儲存',true));

function discardOutput(run,output){if(busy){toast('請等待目前操作完成');return}try{assertTaskActive(p,run.id)}catch(e){toast(e.message,true);return}if(outputInLibrary(output)){toast('這張圖已作為正式參考，請先從素材庫移除後再處理候選',true);return}if(!confirm('從目前工作台移除此候選圖？任務的固定規格與已同步到裝置的圖片會保留。'))return;run.outputs=run.outputs.filter(o=>o.id!==output.id);run.output_events??=[];run.output_events.push({output_id:output.id,action:'candidate_removed',created_at:new Date().toISOString()});run.status=run.outputs.length?'needs_review':'awaiting_import';changed();renderRuns();toast('已移除工作台候選圖')}


$('#deletedTasksBtn').onclick=showDeletedTasks;
